insert into tree_nodes (tree_id, key, stage, kind, category, question, explanation, options, routes, alerts, alternatives, is_anchor, tags, position) values ('00000000-0000-4000-8000-000000000001', 'tera.controle', 'macro', 'yes_no', null, 'Pergunta de controle: o pêndulo está respondendo de forma clara e confiável para esta sessão?', 'Modo T.E.R.A. (inspirado, não oficial): uma pergunta de controle antes de iniciar ajuda a perceber interferências de expectativa.', '[{"value":"sim","label":"Sim","next":"macro.inicio"},{"value":"nao","label":"Não","next":"@stay","hint":"Retome a preparação: respire, solte a expectativa e repita a pergunta de controle."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, array[]::text[], 1) on conflict (tree_id, key) do update set stage = excluded.stage, kind = excluded.kind, category = excluded.category, question = excluded.question, explanation = excluded.explanation, options = excluded.options, routes = excluded.routes, alerts = excluded.alerts, alternatives = excluded.alternatives, is_anchor = excluded.is_anchor, tags = excluded.tags, position = excluded.position;
insert into tree_nodes (tree_id, key, stage, kind, category, question, explanation, options, routes, alerts, alternatives, is_anchor, tags, position) values ('00000000-0000-4000-8000-000000000001', 'macro.inicio', 'macro', 'yes_no', null, 'Existe algum fator prioritário e apropriado para ser investigado em relação ao objetivo desta sessão?', 'Pergunta de abertura. Ela não pressupõe problema: apenas verifica se há algo prioritário e apropriado agora.', '[{"value":"sim","label":"Sim","routes":[{"when":{"var":"mode","eq":"terapeutica"},"next":"terapeutica.camada"},{"next":"macro.dominio"}]},{"value":"nao","label":"Não","next":"fim.sem_prioridade"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Neste momento, é apropriado investigar algum fator prioritário relacionado ao objetivo da sessão?","Há algum aspecto relacionado ao objetivo desta sessão que seja prioritário e apropriado investigar agora?"]'::jsonb, false, array['abertura']::text[], 2) on conflict (tree_id, key) do update set stage = excluded.stage, kind = excluded.kind, category = excluded.category, question = excluded.question, explanation = excluded.explanation, options = excluded.options, routes = excluded.routes, alerts = excluded.alerts, alternatives = excluded.alternatives, is_anchor = excluded.is_anchor, tags = excluded.tags, position = excluded.position;
