insert into tree_nodes (tree_id, key, stage, kind, category, question, explanation, options, routes, alerts, alternatives, is_anchor, tags, position) values ('00000000-0000-4000-8000-000000000001', 'elemento.prioridade', 'priorizar', 'yes_no', null, 'É apropriado aprofundar {{element}} agora, entre as prioridades desta sessão?', 'Desequilíbrio não significa prioridade. Se a resposta for NÃO, o MIRA retorna ao nível anterior.', '[{"value":"sim","label":"Sim","routes":[{"when":{"var":"mode","eq":"tera"},"next":"medir.intensidade"},{"next":"aprofundar.roteador"}],"set":{"priority_confirmed":"sim"}},{"value":"nao","label":"Não","next":"@back"}]'::jsonb, '[]'::jsonb, '[{"when":{"var":"category","eq":"espiritual"},"level":"atencao","message":"Interpretações espirituais pertencem a determinados sistemas de crença e não representam comprovação objetiva do fenômeno. Respeite a crença da consulente e nunca atribua causas a terceiros."},{"when":{"var":"category","eq":"relacionamento"},"level":"info","message":"Investigue a experiência da consulente na relação. Não atribua intenções, culpa ou sentimentos a terceiros."},{"when":{"var":"category","eq":"chakra"},"level":"info","message":"Associações de chakras são simbólicas, dentro do modelo radiestésico utilizado. Nunca as apresente como diagnóstico médico ou psicológico."}]'::jsonb, '["{{element}} está entre as prioridades desta sessão?"]'::jsonb, false, array['regra-prioridade']::text[], 14) on conflict (tree_id, key) do update set stage = excluded.stage, kind = excluded.kind, category = excluded.category, question = excluded.question, explanation = excluded.explanation, options = excluded.options, routes = excluded.routes, alerts = excluded.alerts, alternatives = excluded.alternatives, is_anchor = excluded.is_anchor, tags = excluded.tags, position = excluded.position;
