insert into tree_nodes (tree_id, key, stage, kind, category, question, explanation, options, routes, alerts, alternatives, is_anchor, tags, position) values ('00000000-0000-4000-8000-000000000001', 'aprofundar.categoria', 'aprofundar', 'select', null, 'Qual categoria de hipótese parece mais relacionada a {{element}}?', 'Registre a categoria indicada. Ela orienta a hipótese, sem ser conclusão.', '[{"value":"emocoes","label":"Emoções","set":{"hypothesis_category":"Emoções"},"next":"origem.tipo"},{"value":"crencas","label":"Crenças","set":{"hypothesis_category":"Crenças"},"next":"origem.tipo"},{"value":"habitos","label":"Hábitos","set":{"hypothesis_category":"Hábitos"},"next":"origem.tipo"},{"value":"comportamentos","label":"Comportamentos","set":{"hypothesis_category":"Comportamentos"},"next":"origem.tipo"},{"value":"conflitos_internos","label":"Conflitos internos","set":{"hypothesis_category":"Conflitos internos"},"next":"origem.tipo"},{"value":"experiencias_anteriores","label":"Experiências anteriores","set":{"hypothesis_category":"Experiências anteriores"},"next":"origem.tipo"},{"value":"relacionamentos","label":"Relacionamentos","set":{"hypothesis_category":"Relacionamentos"},"next":"origem.tipo"},{"value":"ambiente","label":"Ambiente","set":{"hypothesis_category":"Ambiente"},"next":"origem.tipo"},{"value":"sobrecarga","label":"Sobrecarga","set":{"hypothesis_category":"Sobrecarga"},"next":"origem.tipo"},{"value":"limites","label":"Limites","set":{"hypothesis_category":"Limites"},"next":"origem.tipo"},{"value":"padroes_familiares_percebidos","label":"Padrões familiares percebidos","set":{"hypothesis_category":"Padrões familiares percebidos"},"next":"origem.tipo"},{"value":"espiritualidade_conforme_crenca_da_consulente","label":"Espiritualidade (conforme crença da consulente)","set":{"hypothesis_category":"Espiritualidade (conforme crença da consulente)","category":"espiritual"},"next":"origem.tipo"},{"value":"nao_definido","label":"Não definido","set":{"hypothesis_