insert into tree_nodes (tree_id, key, stage, kind, category, question, explanation, options, routes, alerts, alternatives, is_anchor, tags, position) values ('00000000-0000-4000-8000-000000000001', 'origem.tipo', 'hipotese', 'origin', null, 'O elemento identificado ({{element}}) parece atuar predominantemente como:', 'Investigação de origem: o resultado é uma hipótese de possível origem simbólico-energética, nunca a "causa real".', '[{"value":"causa","label":"Causa","set":{"origin_role":"causa"},"next":"hipotese.registrar"},{"value":"consequencia","label":"Consequência","set":{"origin_role":"consequencia"},"next":"origem.anterior"},{"value":"ambos","label":"Ambos","set":{"origin_role":"ambos"},"next":"hipotese.registrar"},{"value":"nao_definido","label":"Não definido","set":{"origin_role":"nao_definido"},"next":"hipotese.registrar"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, array[]::text[], 22) on conflict (tree_id, key) do update set stage = excluded.stage, kind = excluded.kind, category = excluded.category, question = excluded.question, explanation = excluded.explanation, options = excluded.options, routes = excluded.routes, alerts = excluded.alerts, alternatives = excluded.alternatives, is_anchor = excluded.is_anchor, tags = excluded.tags, position = excluded.position;
