insert into tree_nodes (tree_id, key, stage, kind, category, question, explanation, options, routes, alerts, alternatives, is_anchor, tags, position) values ('00000000-0000-4000-8000-000000000001', 'hipotese.registrar', 'hipotese', 'text', null, 'Registre a hipótese de possível origem simbólico-energética.', 'Escreva com linguagem de hipótese ("parece", "dentro do modelo utilizado"). Evite afirmações absolutas e não atribua culpa a terceiros.', '[{"value":"registrar","label":"Registrar hipótese","set":{"last_hypothesis":"{{text}}"},"routes":[{"when":{"var":"investigate_prior","eq":"sim"},"next":"origem.reiniciar"},{"next":"intervencao.apropriada"}]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, array['registra-hipotese']::text[], 24) on conflict (tree_id, key) do update set stage = excluded.stage, kind = excluded.kind, category = excluded.category, question = excluded.question, explanation = excluded.explanation, options = excluded.options, routes = excluded.routes, alerts = excluded.alerts, alternatives = excluded.alternatives, is_anchor = excluded.is_anchor, tags = excluded.tags, position = excluded.position;
