insert into charts (name, category, traditional_purpose, origin, description, when_used, when_not_used, tags) select 'Decágono', 'potencializacao', 'Tradicionalmente usado como base para potencializar outros gráficos ou testemunhos.', 'Tradição radiônica popular (origem histórica não verificada)', 'Tradicionalmente usado como base para potencializar outros gráficos ou testemunhos. Descrição tradicional, sem comprovação científica.', 'Como suporte combinado a outro gráfico escolhido na investigação.', 'Não deve ser escolhido automaticamente; apenas se indicado na investigação.', array['potencialização','base']::text[] where not exists (select 1 from charts where name = 'Decágono');
insert into charts (name, category, traditional_purpose, origin, description, when_used, when_not_used, tags) select 'Nove Círculos', 'harmonizacao', 'Tradicionalmente associado a intenções de harmonização e realização de objetivos.', 'Tradição radiônica popular (origem histórica não verificada)', 'Tradicionalmente associado a intenções de harmonização e realização de objetivos. Descrição tradicional, sem comprovação científica.', 'Quando a investigação indicar harmonização relacionada ao objetivo.', 'Não substitui ações práticas nem acompanhamento profissional.', array['harmonização','objetivo']::text[] where not exists (select 1 from charts where name = 'Nove Círculos');
insert into charts (name, category, traditional_purpose, origin, description, when_used, when_not_used, tags) select 'Turbilhão', 'limpeza', 'Tradicionalmente usado em intenções de limpeza simbólico-energética.', 'Tradição radiônica popular (origem histórica não verificada)', 'Tradicionalmente usado em intenções de limpeza simbólico-energética. Descrição tradicional, sem comprovação científica.', 'Quando a investigação indicar limpeza como intervenção apropriada.', 'Evitar uso prolongado sem reavaliação.', array['limpeza']::text[] where not exists (select 1 from charts where name = 'Turbilhão');
insert into charts (name, category, traditional_purpose, origin, description, when_used, when_not_used, tags) select 'Desimpregnador', 'limpeza', 'Tradicionalmente usado para desimpregnação de objetos e ambientes.', 'Tradição radiônica popular (origem histórica não verificada)', 'Tradicionalmente usado para desimpregnação de objetos e ambientes. Descrição tradicional, sem comprovação científica.', 'Harmonização de ambientes e objetos, se indicado.', 'Não usar como resposta automática a queixas.', array['limpeza','ambiente','objeto']::text[] where not exists (select 1 from charts where name = 'Desimpregnador');
insert into charts (name, category, traditional_purpose, origin, description, when_used, when_not_used, tags) select 'Equilibrador de chakras', 'equilibrio', 'Tradicionalmente usado em intenções de equilíbrio do sistema de chakras.', 'Tradição radiônica popular (origem histórica não verificada)', 'Tradicionalmente usado em intenções de equilíbrio do sistema de chakras. Descrição tradicional, sem comprovação científica.', 'Quando a investigação de chakras indicar intervenção apropriada.', 'Associações de chakras não são diagnóstico; não usar para tratar sintomas físicos.', array['chakras','equilíbrio']::text[] where not exists (select 1 from charts where name = 'Equilibrador de chakras');
insert into charts (name, category, traditional_purpose, origin, description, when_used, when_not_used, tags) select 'Escudo simbólico', 'protecao_simbolica', 'Tradicionalmente usado como proteção simbólica, conforme a crença da consulente.', 'Tradição radiônica popular (origem histórica não verificada)', 'Tradicionalmente usado como proteção simbólica, conforme a crença da consulente. Descrição tradicional, sem comprovação científica.', 'Se indicado e coerente com a crença da consulente.', 'Nunca reforçar medo ou ideia de ataque de terceiros.', array['proteção simbólica']::text[] where not exists (select 1 from charts where name = 'Escudo simbólico');
insert into charts (name, category, traditional_purpose, origin, description, when_used, when_not_used, tags) select 'Organizador de prioridades', 'organizacao', 'Usado como apoio simbólico para organização de prioridades e foco.', 'Tradição radiônica popular (origem histórica não verificada)', 'Usado como apoio simbólico para organização de prioridades e foco. Descrição tradicional, sem comprovação científica.', 'Questões de foco, rotina ou organização indicadas na investigação.', '—', array['organização','foco']::text[] where not exists (select 1 from charts where name = 'Organizador de prioridades');
insert into charts (name, category, traditional_purpose, origin, description, when_used, when_not_used, tags) select 'Seta direcional', 'direcionamento', 'Tradicionalmente usado para direcionar a intenção do gráfico principal.', 'Tradição radiônica popular (origem histórica não verificada)', 'Tradicionalmente usado para direcionar a intenção do gráfico principal. Descrição tradicional, sem comprovação científica.', 'Em combinação, quando indicado.', 'Não usar isoladamente sem objetivo definido.', array['direcionamento']::text[] where not exists (select 1 from charts where name = 'Seta direcional');
insert into settings (key, value, description) values ('ai_enabled', 'true'::jsonb, 'Liga/desliga o uso de IA (o sistema funciona sem IA).') on conflict (key) do nothing;
insert into settings (key, value, description) values ('ai_log_content', 'false'::jsonb, 'Grava conteúdo de prompts/respostas em ai_logs (padrão: não, por privacidade).') on conflict (key) do nothing;
insert into settings (key, value, description) values ('consent_text_version', '"v1-2026-10"'::jsonb, 'Versão do termo de consentimento vigente.') on conflict (key) do nothing;
insert into settings (key, value, description) values ('consent_text', '"Autorizo o registro das informações desta ficha e das sessões de radiestesia para fins de acompanhamento terapêutico integrativo, ciente de que a prática não substitui acompanhamento médico ou psicológico e de que posso solicitar a exportação ou exclusão dos meus dados a qualquer momento."'::jsonb, 'Texto do termo de consentimento.') on conflict (key) do nothing;
